INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(125925, 'ruRU', '', 'Ты справился! Я боялась, что мы потеряли тебя во взрыве.', 24330),
(125926, 'ruRU', '', 'Велен вывел нас в безопасное место, прежде чем взрыв настиг нас. Круулу не так повезло.', 24330),
(125940, 'ruRU', '', 'Надеюсь, оно... взорвётся тебе в рожу...', 24330),
(125942, 'ruRU', '', 'Архимаг Зайлем! Ты вернулся...', 24330),
(125943, 'ruRU', '', '...и я больше не чувствую тень внутри тебя!', 24330),
(125945, 'ruRU', '', 'Наездники Лазана поднялись в воздух. Призови его орлов, чтобы они помогли тебе защитить Громовой Тотем!', 24330),
(125947, 'ruRU', '', 'Я подвела... моя королева...', 24330),
(125948, 'ruRU', '', 'Узри могущество, что таится под волнами!', 24330),
(125949, 'ruRU', '', 'Моя королева дала мне власть над морями!', 24330),
(125950, 'ruRU', '', 'Если бы ты отдал Приливный камень, я мог бы оставить тебя в живых...', 24330),
(125951, 'ruRU', '', 'Обглодайте их кости!', 24330),
(125952, 'ruRU', '', 'Не все штормы бьют с небес...', 24330),
(125953, 'ruRU', '', 'Приливная волна сокрушит тебя!', 24330),
(125954, 'ruRU', '', 'Тебе не сопротивляться зову моря!', 24330),
(125955, 'ruRU', '', 'Голодное безумие!', 24330),
(125956, 'ruRU', '', 'Этому фарсу конец ПРЯМО СЕЙЧАС!', 24330),
(125971, 'ruRU', '', 'С отключёнными генераторами щитов можно отдать команду самоуничтожения, чтобы разрушить корабль.', 24330),
(125972, 'ruRU', '', 'К сожалению, у меня нет полномочий, необходимых для отдачи такой команды.', 24330),
(125973, 'ruRU', '', 'Прошу простить меня, господин, но коды самоуничтожения вам придётся ввести самостоятельно.', 24330),
(125974, 'ruRU', '', 'Если вам угодно, лорд Мефистрот, я провожу вас к командной консоли на навигационной палубе.', 24330),
(125975, 'ruRU', '', 'Прошу, держитесь рядом, мой господин.', 24330),
(125979, 'ruRU', '', 'Д\'Бинн, ты жив! Я почти потеряла надежду, мой дорогой друг.', 24330),
(125982, 'ruRU', '', 'Нет времени терять, Клинок Тени. Давай доберёмся до вершины!', 24330),
(125988, 'ruRU', '', 'Ах, вот мы и пришли!', 24330),
(125991, 'ruRU', '', 'Прежде чем принять корону, я должен исполнить просьбу своего брата, в честь моей семьи.\n\nЕсли Эйир знает, кто был виновен в судьбе моей семьи, я хочу услышать это от неё.\n\nСкажи мне, когда будешь готов.', 24330),
(125993, 'ruRU', '', 'Мы на месте! Скоро Легион познает наш гнев.', 24330),
(125994, 'ruRU', '', 'Используй точку спуска, чтобы попасть в пещеру. Дальше я передам инструкции.', 24330),
(125995, 'ruRU', '', 'В самом низу ты найдёшь тайник с порохом, который ты раньше добыл. Обязательно забери его.', 24330),
(125996, 'ruRU', '', 'Также лучше, чтобы тебя здесь не заметили. Эти демоны беспощадны!', 24330),
(125997, 'ruRU', '', 'Хорошо - этот след пороха, что ты оставляешь за собой, ещё пригодится. Теперь выбирайся из пещеры.', 24330),
(125998, 'ruRU', '', 'По пути не забудь оставить дополнительные взрывчатки. Не хотелось бы расстроить Тетис, правда?', 24330),
(126000, 'ruRU', '', 'Ты почти справился! Теперь выбирайся оттуда и подожги порох спичкой, которую дала тебе Тетис.', 24330),
(126001, 'ruRU', '', 'Погоди-ка... он забыл, да? Как я и знала. Похоже, тебе нужен другой способ поджечь этот порох!', 24330),
(126011, 'ruRU', '', 'Ты помог мне защитить эти земли. Теперь моя очередь помочь тебе. Идём, найдём безопасное место для разговора.', 24330),
(126015, 'ruRU', '', 'Когда доберёшься до земли, увидишь бочку. Она полна порохом, пропитанным скверной, который ты... добыл.', 24330),
(126016, 'ruRU', '', 'Кстати, если не хочешь получить клинок скверны в спину, лучше не попадаться тут на глаза.', 24330),
(126017, 'ruRU', '', 'Хорошо. Следующий шаг прост - просто выберись из этой пещеры незамеченным. Порох сделает своё дело.', 24330),
(126018, 'ruRU', '', 'Хотя, вот ещё что. Заложи немного взрывчатки вокруг для небольшого дополнительного "бум".', 24330),
(126019, 'ruRU', '', 'Хорошо, дело почти сделано. Просто выберись из пещеры и подожги порох спичкой, которую дала тебе Тетис.', 24330),
(126021, 'ruRU', '', 'Погоди-ка... этот пьяный шут забыл, да? Тебе лучше найти способ поджечь этот порох, $ct. Я не позволю этой миссии провалиться!', 24330);
